import { Router, Response } from 'express';
import { z } from 'zod';
import { v4 as uuidv4 } from 'uuid';
import { AuthenticatedRequest } from '../types.js';
import { getSupabaseClient, isRealSupabaseConfigured, mockDb } from '../services/supabase.js';
import type { MonitoredSite, MonitorCheck, MonitoredSiteWithLatestCheck } from '@pingwatch/shared';

const router = Router();

const createSiteSchema = z.object({
  name: z.string().min(1, 'Name is required').max(100, 'Name must be 100 characters or less'),
  url: z
    .string()
    .url('Must be a valid URL')
    .refine((val) => val.startsWith('https://'), {
      message: 'URL must use HTTPS protocol',
    }),
  check_interval_s: z.union([z.literal(60), z.literal(300), z.literal(600)]),
});

// POST /sites - Add new site to monitor
router.post('/', async (req: AuthenticatedRequest, res: Response): Promise<void> => {
  try {
    const parseResult = createSiteSchema.safeParse(req.body);
    if (!parseResult.success) {
      res.status(400).json({ error: 'Validation failed', details: parseResult.error.flatten() });
      return;
    }

    const { name, url, check_interval_s } = parseResult.data;
    const userId = req.user!.id;

    if (isRealSupabaseConfigured()) {
      const supabase = getSupabaseClient();
      const { data, error } = await supabase
        .from('monitored_sites')
        .insert({
          user_id: userId,
          name,
          url,
          check_interval_s,
          is_active: true,
          last_status: 'unknown',
        })
        .select()
        .single();

      if (error) {
        res.status(500).json({ error: error.message });
        return;
      }
      res.status(201).json(data);
      return;
    }

    // Mock DB fallback
    const newSite: MonitoredSite = {
      id: uuidv4(),
      user_id: userId,
      name,
      url,
      check_interval_s,
      is_active: true,
      last_status: 'unknown',
      last_checked_at: null,
      created_at: new Date().toISOString(),
    };

    mockDb.sites.unshift(newSite);
    res.status(201).json(newSite);
  } catch (err: any) {
    res.status(500).json({ error: err.message || 'Failed to create site' });
  }
});

// GET /sites - Get all monitored sites for user with latest check
router.get('/', async (req: AuthenticatedRequest, res: Response): Promise<void> => {
  try {
    const userId = req.user!.id;

    if (isRealSupabaseConfigured()) {
      const supabase = getSupabaseClient();
      const { data: sites, error: sitesError } = await supabase
        .from('monitored_sites')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (sitesError) {
        res.status(500).json({ error: sitesError.message });
        return;
      }

      if (!sites || sites.length === 0) {
        res.json([]);
        return;
      }

      const siteIds = sites.map((s) => s.id);
      const { data: checks, error: checksError } = await supabase
        .from('monitor_checks')
        .select('*')
        .in('site_id', siteIds)
        .order('checked_at', { ascending: false });

      if (checksError) {
        console.error('Error fetching checks:', checksError);
      }

      const sitesWithChecks: MonitoredSiteWithLatestCheck[] = sites.map((site) => {
        const latest = checks?.find((c) => c.site_id === site.id);
        return {
          ...site,
          latest_check: latest || null,
        };
      });

      res.json(sitesWithChecks);
      return;
    }

    // Mock DB fallback
    const userSites = mockDb.sites.filter((s) => s.user_id === userId);
    const sitesWithChecks: MonitoredSiteWithLatestCheck[] = userSites.map((site) => {
      const siteChecks = mockDb.checks.filter((c) => c.site_id === site.id);
      const latest = siteChecks.sort(
        (a, b) => new Date(b.checked_at).getTime() - new Date(a.checked_at).getTime()
      )[0];
      return {
        ...site,
        latest_check: latest || null,
      };
    });

    res.json(sitesWithChecks);
  } catch (err: any) {
    res.status(500).json({ error: err.message || 'Failed to fetch sites' });
  }
});

// DELETE /sites/:siteId - Delete a monitored site
router.delete('/:siteId', async (req: AuthenticatedRequest, res: Response): Promise<void> => {
  try {
    const { siteId } = req.params;
    const userId = req.user!.id;

    if (isRealSupabaseConfigured()) {
      const supabase = getSupabaseClient();
      const { error } = await supabase
        .from('monitored_sites')
        .delete()
        .eq('id', siteId)
        .eq('user_id', userId);

      if (error) {
        res.status(500).json({ error: error.message });
        return;
      }
      res.status(200).json({ success: true, message: 'Site deleted successfully' });
      return;
    }

    const index = mockDb.sites.findIndex((s) => s.id === siteId && s.user_id === userId);
    if (index === -1) {
      res.status(404).json({ error: 'Site not found or access denied' });
      return;
    }

    mockDb.sites.splice(index, 1);
    mockDb.checks = mockDb.checks.filter((c) => c.site_id !== siteId);
    mockDb.incidents = mockDb.incidents.filter((i) => i.site_id !== siteId);
    mockDb.alertChannels = mockDb.alertChannels.filter((a) => a.site_id !== siteId);

    res.status(200).json({ success: true, message: 'Site deleted successfully' });
  } catch (err: any) {
    res.status(500).json({ error: err.message || 'Failed to delete site' });
  }
});

export default router;
